44			// name validation
45			if (!StringUtils.hasText(name)) {
46				errors.rejectValue("name", REQUIRED, REQUIRED);
47			}
48			else if (name.length() > MAX_NAME_LENGTH) {
49				errors.rejectValue("name", "size", "Name must be no more than 30 characters");
50			}
51	
52			// type validation
53			if (pet.isNew() && pet.getType() == null) {
54				errors.rejectValue("type", REQUIRED, REQUIRED);
55			}
56	
57			// birth date validation
58			if (pet.getBirthDate() == null) {
59				errors.rejectValue("birthDate", REQUIRED, REQUIRED);
60			}
61			else if (pet.getBirthDate().isAfter(LocalDate.now())) {
62				errors.rejectValue("birthDate", "typeMismatch.birthDate");
63			}
64		}
65	
66		/**
67		 * This Validator validates *just* Pet instances
68		 */
69		@Override
70		public boolean supports(Class<?> clazz) {
71			return Pet.class.isAssignableFrom(clazz);
72		}
73	
74	}
