2	
3	import static org.assertj.core.api.Assertions.assertThat;
4	
5	import java.util.Optional;
6	import java.util.concurrent.CountDownLatch;
7	import java.util.concurrent.ExecutorService;
8	import java.util.concurrent.Executors;
9	import java.util.concurrent.TimeUnit;
10	import java.util.concurrent.atomic.AtomicInteger;
11	
12	import org.junit.jupiter.api.Test;
13	import org.springframework.beans.factory.annotation.Autowired;
14	import org.springframework.boot.test.context.SpringBootTest;
15	import org.springframework.boot.test.context.SpringBootTest.WebEnvironment;
16	import org.springframework.boot.test.web.server.LocalServerPort;
17	import org.springframework.boot.restclient.RestTemplateBuilder;
18	import org.springframework.http.HttpEntity;
19	import org.springframework.http.HttpHeaders;
20	import org.springframework.http.MediaType;
21	import org.springframework.http.ResponseEntity;
22	import org.springframework.samples.petclinic.owner.Owner;
23	import org.springframework.samples.petclinic.owner.OwnerRepository;
24	import org.springframework.util.LinkedMultiValueMap;
25	import org.springframework.util.MultiValueMap;
26	import org.springframework.web.client.RestTemplate;
27	
28	@SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT)
29	public class PetClinicConcurrencyTests {
30	
31		@LocalServerPort
32		private int port;
33	
34		@Autowired
35		private OwnerRepository ownerRepository;
36	
37		@Autowired
38		private RestTemplateBuilder restTemplateBuilder;
39	
40		@Test
41		public void testDuplicatePetNameRaceConditionIsBlocked() throws Exception {
42			int ownerId = 1;
43			Optional<Owner> initialOwnerOpt = ownerRepository.findById(ownerId);
44			assertThat(initialOwnerOpt).isPresent();
45			Owner owner = initialOwnerOpt.get();
46	
47			int initialPetCount = owner.getPets().size();
48			String duplicatePetName = "ConcurrencyTestPet";
49	
50			// Ensure duplicate pet name does not exist yet
51			assertThat(owner.getPet(duplicatePetName)).isNull();
52	
53			RestTemplate template = restTemplateBuilder.baseUri("http://localhost:" + port).build();
54	
55			int threadCount = 2;
56			ExecutorService executorService = Executors.newFixedThreadPool(threadCount);
57			CountDownLatch readyLatch = new CountDownLatch(threadCount);
58			CountDownLatch startLatch = new CountDownLatch(1);
59			CountDownLatch doneLatch = new CountDownLatch(threadCount);
60	
61			AtomicInteger successCount = new AtomicInteger(0);
62			AtomicInteger failureCount = new AtomicInteger(0);
63	
64			for (int i = 0; i < threadCount; i++) {
65				executorService.submit(() -> {
66					readyLatch.countDown();
67					try {
68						startLatch.await(); // Wait to start simultaneously
69	
70						HttpHeaders headers = new HttpHeaders();
71						headers.setContentType(MediaType.APPLICATION_FORM_URLENCODED);
72	
73						MultiValueMap<String, String> map = new LinkedMultiValueMap<>();
74						map.add("name", duplicatePetName);
75						map.add("birthDate", "2020-01-01");
76						map.add("type", "cat");
77	
78						HttpEntity<MultiValueMap<String, String>> request = new HttpEntity<>(map, headers);
79	
80						ResponseEntity<String> response = template.postForEntity("/owners/" + ownerId + "/pets/new",
81								request, String.class);
82	
83						String body = response.getBody();
84						// If the response page contains the duplicate validation error, it
85						// was blocked
86						if (response.getStatusCode().is2xxSuccessful()
87								&& (body == null || !body.contains("is already in use"))) {
88							successCount.incrementAndGet();
89						}
90						else {
91							failureCount.incrementAndGet();
92						}
93					}
94					catch (Exception e) {
95						failureCount.incrementAndGet();
96					}
97					finally {
98						doneLatch.countDown();
99					}
100				});
101			}
102	
103			try {
104				boolean ready = readyLatch.await(10, TimeUnit.SECONDS);
105				assertThat(ready).isTrue();
106				startLatch.countDown();
107				boolean completed = doneLatch.await(10, TimeUnit.SECONDS);
108				assertThat(completed).isTrue();
109			}
110			finally {
111				executorService.shutdown();
112			}
113	
114			Owner updatedOwner = ownerRepository.findById(ownerId).get();
115			int newPetCount = updatedOwner.getPets().size();
116	
117			System.out.println("--- Concurrency Test Assertions ---");
118			System.out.println("Successful additions: " + successCount.get());
119			System.out.println("Failed additions: " + failureCount.get());
120			System.out.println("Original Pet Count: " + initialPetCount);
121			System.out.println("Final Pet Count: " + newPetCount);
122	
123			// With the fix, exactly ONE concurrent request must succeed
124			assertThat(successCount.get()).isEqualTo(1);
125			assertThat(newPetCount).isEqualTo(initialPetCount + 1);
126	
127			long countWithDuplicateName = updatedOwner.getPets()
128				.stream()
129				.filter(p -> duplicatePetName.equalsIgnoreCase(p.getName()))
130				.count();
131			assertThat(countWithDuplicateName).isEqualTo(1);
132		}
133	
134	}
